def mname(m, lang):
    return METHOD[m][0 if lang == 'en' else 1]


def dname(d):
    return DISTRICT.get(d, d.replace('_', ' '))


# ------------------------------------------------------------------ formatting
def num(x, dec, lang, sign=False):
    """1,562,596 / 0.258 in English; 1 562 596 / 0,258 in French; $-$ for minus."""
    if x is None or (isinstance(x, float) and math.isnan(x)):
        return 'n.a.' if lang == 'en' else 'n.d.'
    s = f"{abs(x):,.{dec}f}"
    if lang == 'fr':
        s = s.replace(',', r'\,').replace('.', ',')
    if x < 0 and float(s.replace(r'\,', '').replace(',', '.')) != 0:
        s = '$-$' + s
    elif sign and x > 0:
        s = '+' + s
    return s


def pct(x, dec, lang):
    return num(x, dec, lang) + r'~\%'


def pval(p, lang):
    """p-value: 3 decimals, or "< 0.001" (step 8b, R2-m32: the p-values measure
    simulation uncertainty, so their exact size below 0.001 carries no meaning).
    "$p$ = $<$ ..." is turned into "$p$ $<$ ..." in write_all()."""
    if p < 0.001:
        return '$<$ ' + num(0.001, 3, lang)
    return num(p, 3, lang)


def ci(lo, hi, dec, lang):
    sep = ' ; ' if lang == 'fr' else ', '
    return f"[{num(lo, dec, lang)}{sep}{num(hi, dec, lang)}]"


def T(en, fr, lang):
    return en if lang == 'en' else fr


# ------------------------------------------------------------------ numbering
class Numbering:
    """Global numbering of tables and figures across the six files (S1, S2, ...)."""
    def __init__(self):
        self.tab = 0
        self.fig = 0
        self.rows = []

    def table(self, key, af):
        self.tab += 1
        self.rows.append((key, af, 'table', self.tab))
        return self.tab

    def figure(self, key, af):
        self.fig += 1
        self.rows.append((key, af, 'figure', self.fig))
        return self.fig


def table_env(n, caption, colspec, header, body, note=None, size='footnotesize'):
    out = [r"\begin{table}[!htbp]", r"\setcounter{table}{%d}" % (n - 1),
           r"\caption{%s}" % caption, "\\" + size, r"\setlength{\tabcolsep}{%s}" % ('2pt' if size == 'scriptsize' else '3pt'),
           r"\begin{tabular*}{\textwidth}{@{\extracolsep\fill}%s}" % colspec, r"\toprule",
           header, r"\midrule", body, r"\bottomrule", r"\end{tabular*}"]
    if note:
        out.append(r"\par\smallskip{\scriptsize %s\par}" % note)
    out.append(r"\end{table}")
    return "\n".join(out) + "\n"


def src(paths, lang):
    p = ', '.join(r'\code{%s}' % x.replace('_', r'\_') for x in paths)
    return T('Source: ', 'Source : ', lang) + p + '.'


