SEL = rd(MET, 'selected_variant.csv')
N_SCEN = len(ML)
README = open(os.path.join(DER, 'reference_2018_2025_README.txt'), encoding='utf-8').read()


def readme_int(pattern):
    m = re.search(pattern, README)
    if not m:
        sys.exit('README pattern not found: ' + pattern)
    return int(m.group(1))


# ================================================================== AF1
def af1(lang, nb):
    ctx = rd(DER, 'district_context_minsante2023.csv')
    car = rd(DER, 'reference_characteristics.csv')
    t1, t2 = nb.table('S_context', 1), nb.table('S_series', 1)
    rows = []
    for _, r in ctx.iterrows():
        rows.append(f"{dname(r.district)} & {num(r.population_2023,0,lang)} & {num(r.area_km2,1,lang)} & "
                    f"{num(r.health_areas,0,lang)} & {num(r.public_facilities_by_category,0,lang)} & "
                    f"{num(r.public_facilities_coverage,0,lang)} & {num(r.private_facilities_coverage,0,lang)} \\\\")
    s = ctx.drop(columns='district').sum(min_count=1)
    n_area = ctx.health_areas.notna().sum()
    rows.append(r"\midrule")
    rows.append(f"\\textbf{{{T('Sum', 'Somme', lang)}}} & {num(s.population_2023,0,lang)} & {num(s.area_km2,1,lang)} & "
                f"{num(s.health_areas,0,lang)} & {num(s.public_facilities_by_category,0,lang)} & "
                f"{num(s.public_facilities_coverage,0,lang)} & {num(s.private_facilities_coverage,0,lang)} \\\\")
    nr = ctx.set_index('district').loc['Ngaoundere_Rural']
    belel_missing = ctx.set_index('district').loc['Belel'].isna().sum()
    assert belel_missing >= 2
    head1 = T(r"District & Population & Area & Health & Public & Public & Private \\ & 2023 & (km\textsuperscript{2}) & areas & facilities (a) & facilities (b) & facilities (b) \\",
              r"District & Population & Superficie & Aires & Formations & Formations & Formations \\ & 2023 & (km\textsuperscript{2}) & de santé & publiques (a) & publiques (b) & privées (b) \\", lang)
    note1 = T(
        f"Source: Ministry of Public Health of Cameroon, \\textit{{Carte sanitaire programmatique officielle}}, January 2023, transcribed in \\code{{data/derived/district\\_context\\_minsante2023.csv}}. (a) Table of public facilities by category. (b) Table of coverage, ratios and available sites. The two source tables disagree and are reported without correction; for Ngaoundéré Rural they give {num(nr.public_facilities_by_category,0,lang)} and {num(nr.public_facilities_coverage,0,lang)} public facilities, which suggests that table (b) counts Belel with that district. ``n.a.'': value absent from the source. Sums are taken over the districts with a value ({n_area} districts for health areas). The population is that of 2023; the series cover {YEAR0} to {YEAR1}.",
        f"Source : Ministère de la Santé publique du Cameroun, \\textit{{Carte sanitaire programmatique officielle}}, janvier 2023, transcrite dans \\code{{data/derived/district\\_context\\_minsante2023.csv}}. (a) Tableau des formations publiques par catégorie. (b) Tableau de la couverture, des ratios et des sites disponibles. Les deux tableaux de la source ne concordent pas et sont rapportés sans correction ; pour Ngaoundéré Rural, ils donnent {num(nr.public_facilities_by_category,0,lang)} et {num(nr.public_facilities_coverage,0,lang)} formations publiques, ce qui laisse penser que le tableau (b) compte Belel avec ce district. « n.d. » : valeur absente de la source. Les sommes portent sur les districts renseignés ({n_area} districts pour les aires de santé). La population est celle de 2023 ; les séries couvrent {YEAR0} à {YEAR1}.", lang)
    tab1 = table_env(t1, T('Population, area, health areas and health facilities by district.',
                           'Population, superficie, aires de santé et formations sanitaires par district.', lang),
                     'lrrrrrr', head1, "\n".join(rows), note1)
    rows2 = "\n".join(
        f"{dname(r.district)} & {num(r['mean'],1,lang)} & {num(r.sd,1,lang)} & {num(r.cv,3,lang)} & {num(r['min'],0,lang)} & "
        f"{num(r['max'],0,lang)} & {num(r.autocorr_lag1,3,lang)} & {num(r.autocorr_lag52,3,lang)} & "
        f"{num(r.mean_corr_other_districts,3,lang)} & {num(r.seasonal_r2,3,lang)} \\\\" for _, r in car.iterrows())
    assert (car.n_zeros == 0).all()
    head2 = T(r"District & Mean & SD & CV & Min. & Max. & ACF & ACF & Mean & Seasonal \\ & & & & & & lag 1 & lag 52 & corr. & $R^2$ \\",
              r"District & Moyenne & É.-t. & CV & Min. & Max. & Autocorr. & Autocorr. & Corr. & $R^2$ \\ & & & & & & rang 1 & rang 52 & moyenne & saisonnier \\", lang)
    note2 = T(
        "Confirmed malaria cases per week. SD: standard deviation. CV: coefficient of variation. ACF: autocorrelation at the stated lag, in weeks. Mean corr.: mean of the Pearson correlations of the district with each of the other ten. Seasonal $R^2$: share of variance explained by the mean seasonal profile of the district. No district contains a zero count. " + src(['data/derived/reference_characteristics.csv'], lang),
        "Cas confirmés de paludisme par semaine. É.-t. : écart-type. CV : coefficient de variation. Autocorr. : autocorrélation au rang indiqué, en semaines. Corr. moyenne : moyenne des corrélations de Pearson du district avec chacun des dix autres. $R^2$ saisonnier : part de variance expliquée par le profil saisonnier moyen du district. Aucun district ne contient de comptage nul. " + src(['data/derived/reference_characteristics.csv'], lang), lang)
    tab2 = table_env(t2, T(f'Structural characteristics of the eleven weekly reference series ({N_WEEKS} weeks, {YEAR0}--{YEAR1}).',
                           f'Caractéristiques structurelles des onze séries hebdomadaires de référence ({N_WEEKS} semaines, {YEAR0}--{YEAR1}).', lang),
                     'lrrrrrrrrr', head2, rows2, note2)
    intro = T(f"Two tables: the demographic and health-service context of the districts (Table~S{t1}) and the structural characteristics of the eleven weekly series (Table~S{t2}). None of these variables enters the imputation; they describe the units studied.\n\n",
              f"Deux tableaux : le contexte démographique et sanitaire des districts (tableau~S{t1}) et les caractéristiques structurelles des onze séries hebdomadaires (tableau~S{t2}). Aucune de ces variables n'entre dans l'imputation ; elles décrivent les unités étudiées.\n\n", lang)
    head = T(r"\section*{Additional file 1. Description of the eleven health districts}", r"\section*{Fichier additionnel 1. Description des onze districts sanitaires}", lang)
    return head + "\n\n" + intro + tab1 + "\n" + tab2


# ================================================================== AF2
def af2(lang, nb):
    out = [T(r"\section*{Additional file 2. Design details}", r"\section*{Fichier additionnel 2. Détails de conception}", lang),
           T("This file documents the construction of the reference series, the masks, the verification of the MCAR simulation, the reduced mechanism design and the implementation choices referred to in the Methods of the main text. Each table gives the analysis output it is read from.",
             "Ce fichier documente la construction de la série de référence, les masques, la vérification de la simulation MCAR, le plan réduit des mécanismes et les choix d'implémentation auxquels renvoient les Méthodes du texte principal. Chaque tableau indique la sortie d'analyse dont il est tiré.", lang)]

    # 1. reference series
    ident = readme_int(r'identical cells\s*:\s*(\d+)')
    differ = readme_int(r'different cells\s*:\s*(\d+)')
    ncells = readme_int(r'\(\d+ weeks, (\d+) cells\)')
    total_2018_2022 = readme_int(r'unchanged \((\d+)\)')
    n_append = readme_int(r'2023-2025 : appended from .*?\((\d+) weeks\)')
    ov = rd(DER, 'reference_2018_2025_overlap_differences.csv')
    assert len(ov) == differ and ident + differ == ncells
    t_ov = nb.table('S_overlap', 2)
    rows = "\n".join(f"{r.periodid} & {dname(r.district)} & {num(r.value_new_file,0,lang)} & {num(r.value_reference_kept,0,lang)} & {num(r.difference,0,lang,sign=True)} \\\\" for _, r in ov.iterrows())
    out.append(T(r"\subsection*{1. Construction of the reference series}", r"\subsection*{1. Construction de la série de référence}", lang))
    out.append(T(
        f"The reference series was built by \\code{{data/extend\\_reference\\_2018\\_2025.py}} in three steps. (i) In the 2018--2022 series, the row dated 27 December 2020 held the sum of ISO weeks 52 and 53 of 2020, so that every later date was one week early; the row was split and the later dates shifted by seven days, which leaves the 2018--2022 total unchanged ({num(total_2018_2022,0,lang)} cases). (ii) Over 2021 and 2022, covered by both extracts, {num(ident,0,lang)} of the {num(ncells,0,lang)} cells are identical; the {differ} others are listed in Table~S{t_ov}, and the value of the 2018--2022 series was kept. (iii) The {n_append} weeks of 2023 to 2025 were appended from the 2021--2025 extract. The district of Mayo-Baleo, absent from the 2018--2022 series and without any non-zero count over 2021--2025, was not included. A check for imputations made upstream of this study looked for cells equal to the overall or annual mean of their column; it flagged only the Belel cell (Additional file 3). This check detects neither an imputation rounded to an integer nor a value carried over from a neighbouring week.",
        f"La série de référence a été construite par \\code{{data/extend\\_reference\\_2018\\_2025.py}} en trois étapes. (i) Dans la série 2018--2022, la ligne datée du 27 décembre 2020 contenait la somme des semaines ISO 52 et 53 de 2020, si bien que toutes les dates suivantes avaient une semaine d'avance ; la ligne a été scindée et les dates suivantes décalées de sept jours, ce qui laisse inchangé le total 2018--2022 ({num(total_2018_2022,0,lang)} cas). (ii) Sur 2021 et 2022, couvertes par les deux extractions, {num(ident,0,lang)} des {num(ncells,0,lang)} cellules sont identiques ; les {differ} autres figurent au tableau~S{t_ov}, et la valeur de la série 2018--2022 a été conservée. (iii) Les {n_append} semaines de 2023 à 2025 ont été ajoutées depuis l'extraction 2021--2025. Le district de Mayo-Baleo, absent de la série 2018--2022 et sans aucun comptage non nul sur 2021--2025, n'a pas été inclus. Un contrôle des imputations faites en amont a recherché les cellules égales à la moyenne générale ou annuelle de leur colonne ; il n'a signalé que la cellule de Belel (fichier additionnel 3). Ce contrôle ne détecte ni une imputation arrondie à l'entier, ni une valeur reportée d'une semaine voisine.", lang))
    out.append(table_env(t_ov, T('Cells of 2021--2022 that differ between the two extracts.', 'Cellules de 2021--2022 qui diffèrent entre les deux extractions.', lang),
                         'llrrr', T(r"Week ending & District & 2021--2025 extract & Value kept & Difference \\", r"Semaine finissant le & District & Extraction 2021--2025 & Valeur conservée & Écart \\", lang),
                         rows, src(['data/derived/reference_2018_2025_overlap_differences.csv'], lang)))

    # 2. 2023 peaks and first-half drop
    pk = rd(DER, 'peaks_2023_checks.csv')
    t_pk = nb.table('S_peaks', 2)
    years = sorted(pk.year.unique())
    rows = []
    for d, g in pk.groupby('district', sort=False):
        g = g.set_index('year')
        rows.append(dname(d) + ' & ' + ' & '.join(f"{num(g.loc[y,'max_sep_dec'],0,lang)} ({int(g.loc[y,'any_flag'])})" for y in years) + r' \\')
    flags23 = int(pk[pk.year == 2023].any_flag.sum())
    weeks23 = int(pk[pk.year == 2023].n_weeks_sep_dec.sum())
    other = pk[pk.year != 2023].groupby('year').any_flag.sum()
    assert flags23 == 0
    lb = rd(DER, 'level_break_2023_check.csv')
    t_lb = nb.table('S_level', 2)
    drop = 100 * (1 - lb.ratio_2023_2022)
    assert (lb.ratio_2023_2022 < 1).all()
    rows_lb = "\n".join(f"{dname(r.district)} & {num(r.mean_h1_2022,1,lang)} & {num(r.mean_h1_2023,1,lang)} & {num(r.mean_h1_2024,1,lang)} & {num(r.ratio_2023_2022,3,lang)} & {num(r.ratio_2024_2023,3,lang)} \\\\" for _, r in lb.iterrows())
    out.append(T(r"\subsection*{2. Autumn 2023 peaks and first-half 2023 counts}", r"\subsection*{2. Pics de l'automne 2023 et comptages du premier semestre 2023}", lang))
    out.append(T(
        f"Four checks were applied by \\code{{data/check\\_peaks\\_2023.py}} to every week of September to December, each year, in the three districts whose autumn 2023 counts are the highest of the period: equality with the mean or the median of the series, repetition of the previous week, equality with the mean of the two neighbouring weeks, and equality with the sum or the double of a neighbour. None of the {weeks23} weeks of autumn 2023 is flagged; the other years have {int(other.min())} to {int(other.max())} flagged weeks over the three districts (Table~S{t_pk}). Over the eleven districts, mean weekly counts of the first half of 2023 are {num(drop.min(),0,lang)} to {num(drop.max(),0,lang)}\\% lower than in the first half of 2022 (Table~S{t_lb}).",
        f"Quatre contrôles ont été appliqués par \\code{{data/check\\_peaks\\_2023.py}} à chaque semaine de septembre à décembre, chaque année, dans les trois districts dont les comptages de l'automne 2023 sont les plus élevés de la période : égalité avec la moyenne ou la médiane de la série, répétition de la semaine précédente, égalité avec la moyenne des deux semaines voisines, et égalité avec la somme ou le double d'une voisine. Aucune des {weeks23} semaines de l'automne 2023 n'est signalée ; les autres années comptent de {int(other.min())} à {int(other.max())} semaines signalées sur les trois districts (tableau~S{t_pk}). Dans les onze districts, les comptages hebdomadaires moyens du premier semestre 2023 sont inférieurs de {num(drop.min(),0,lang)} à {num(drop.max(),0,lang)}~\\% à ceux du premier semestre 2022 (tableau~S{t_lb}).", lang))
    out.append(table_env(t_pk, T('Highest weekly count of September--December and number of flagged weeks (in brackets), by year.',
                                 'Plus fort comptage hebdomadaire de septembre à décembre et nombre de semaines signalées (entre parenthèses), par année.', lang),
                         'l' + 'r' * len(years), 'District & ' + ' & '.join(str(y) for y in years) + r' \\', "\n".join(rows),
                         src(['data/derived/peaks_2023_checks.csv'], lang)))
    out.append(table_env(t_lb, T('Mean weekly counts of January--June, by year, and ratios between years.', 'Comptages hebdomadaires moyens de janvier à juin, par année, et rapports entre années.', lang),
                         'lrrrrr', T(r"District & 2022 & 2023 & 2024 & 2023/2022 & 2024/2023 \\", r"District & 2022 & 2023 & 2024 & 2023/2022 & 2024/2023 \\", lang),
                         rows_lb, src(['data/derived/level_break_2023_check.csv'], lang)))

    # 3. Belel
    fl = rd(DER, 'reference_flagged_cells.csv').iloc[0]
    out.append(T(r"\subsection*{3. The Belel cell}", r"\subsection*{3. La cellule de Belel}", lang))
    out.append(T(f"The value stored for {fl.district} in the week ending {fl.periodid} ({num(fl.source_value,3,lang)}) is the district's 2019 annual mean, filled in upstream of this study. It was replaced by {int(fl.retained_value)} and excluded from every metric; Additional file 3 compares seven candidate values.",
                 f"La valeur enregistrée pour {fl.district} la semaine finissant le {fl.periodid} ({num(fl.source_value,3,lang)}) est la moyenne annuelle 2019 du district, renseignée en amont de cette étude. Elle a été remplacée par {int(fl.retained_value)} et exclue de toutes les métriques ; le fichier additionnel 3 compare sept valeurs candidates.", lang))

    # 4. masks
    gd = rd(MET, 'gap_length_distribution.csv')
    t_gd = nb.table('S_gaplen', 2)
    rows = "\n".join(
        f"{num(r.missing_rate,0,lang)} & {num(r.gap_length,0,lang)} & {num(r.target_cells,0,lang)} & {num(r.overshoot_cells_max,0,lang)} & "
        f"{num(r.mean_run_length,2,lang)} & {num(r.max_run_length,0,lang)} & {pct(100*r.share_cells_longer_than_nominal,1,lang)} & "
        f"{pct(100*r.share_blocks_overlapping,1,lang) if r.gap_length > 1 else '--'} & {int(r.masks_with_last_week_masked)}/{int(r.n_masks)} \\\\"
        for _, r in gd.iterrows())
    long_ = gd[gd.gap_length > 1]
    assert (long_.masks_with_last_week_masked == 0).all() and (long_.last_masked_row_max < N_WEEKS).all()
    g20 = gd[(gd.missing_rate == 20) & (gd.gap_length == 1)].iloc[0]
    out.append(T(r"\subsection*{4. Masks: constraints, seeds and effective gap lengths}", r"\subsection*{4. Masques : contraintes, graines et longueurs effectives des lacunes}", lang))
    out.append(T(
        f"Masks were applied to the district columns only. Each mask was checked to leave at least {MIN_OBS_DISTRICT} observed values in each district and at least {MIN_OBS_WEEK_MCAR} in each week; every mask passed, so the check never discarded a draw. Each mask was drawn with the seed \\code{{{SEED_MASK}}} and saved, so that every configuration can be regenerated. Cells (one-week gaps) and blocks (four- and eight-week gaps) are drawn independently, so that neighbouring gaps can touch or overlap: the gap lengths are nominal. Table~S{t_gd} gives the effective lengths. At 20\\%, {pct(100*g20.share_cells_run_ge_2,1,lang)} of the cells masked as one-week gaps lie in runs of two weeks or more. For four- and eight-week gaps, the last week of the series is never masked, because a block must start early enough to fit inside the series.",
        f"Le masquage n'a porté que sur les colonnes de districts. Chaque masque a été contrôlé : au moins {MIN_OBS_DISTRICT} valeurs observées par district et au moins {MIN_OBS_WEEK_MCAR} par semaine ; tous les masques ont passé ce contrôle, qui n'a donc écarté aucun tirage. Chaque masque a été tiré avec la graine \\code{{{SEED_MASK}}} et enregistré, de sorte que toute configuration peut être régénérée. Les cellules (lacunes d'une semaine) et les blocs (lacunes de quatre et huit semaines) sont tirés indépendamment, si bien que des lacunes voisines peuvent se toucher ou se chevaucher : les longueurs sont nominales. Le tableau~S{t_gd} donne les longueurs effectives. À 20~\\%, {pct(100*g20.share_cells_run_ge_2,1,lang)} des cellules masquées comme lacunes d'une semaine appartiennent à des séquences de deux semaines ou plus. Pour les lacunes de quatre et huit semaines, la dernière semaine de la série n'est jamais masquée.", lang))
    out.append(table_env(t_gd, T('Effective gap lengths of the 180 masks of the main design.', 'Longueurs effectives des lacunes des 180 masques du plan principal.', lang),
                         'rrrrrrrrr',
                         T(r"Rate & Gap & Target & Max. & Mean run & Max. & Cells in runs & Blocks & Masks with \\ (\%) & (weeks) & cells & excess & length & run & longer than nominal & overlapping & last week masked \\",
                           r"Taux & Lacune & Cellules & Excès & Longueur & Séquence & Cellules en séquences & Blocs & Masques avec \\ (\%) & (sem.) & cibles & max. & moyenne & max. & plus longues que nominal & chevauchants & dernière semaine masquée \\", lang),
                         rows, size='scriptsize', note=T("Run: maximal sequence of consecutive masked weeks in a district column. ", "Séquence : suite maximale de semaines masquées consécutives dans une colonne de district. ", lang) + src(['output/metrics/gap_length_distribution.csv'], lang)))

    # 5. MCAR verification
    mv = rd(MET, 'mcar_validation.csv')
    t_mv, t_pn = nb.table('S_mcar_pass', 2), nb.table('S_mcar_null', 2)
    rows = []
    for g, d in mv.groupby('gap_length'):
        rows.append(f"{int(g)} & {len(d)} & {pct(100*(d.p_time>ALPHA).mean(),1,lang)} & {pct(100*(d.p_values_ks>ALPHA).mean(),1,lang)} & "
                    f"{pct(100*(d.p_districts>ALPHA).mean(),1,lang)} & {pct(d.pct_pairs_significant.mean(),1,lang)} & {pct(100*d.valid.mean(),1,lang)} \\\\")
    ut = rd(MET, 'mcar_uniformity_tests.csv').set_index('test')
    bt = ut.loc['binomial_failures']
    pn = rd(MET, 'mcar_pvalue_null.csv')
    rows_pn = "\n".join(f"{r.variable.replace('p_districts', T('districts','districts',lang)).replace('p_time', T('time','temps',lang))} & {r.missing_rate if r.missing_rate=='all' else num(float(r.missing_rate),0,lang)} & {num(r.n_sim,0,lang)} & {num(r.sim_mean_p,3,lang)} & {num(r.n_obs,0,lang)} & {num(r.obs_mean_p,3,lang)} & {pval(r.ks_obs_vs_sim_p,lang)} & {pval(r.ks_obs_vs_uniform_p,lang)} \\\\" for _, r in pn.iterrows()).replace('all', T('all', 'tous', lang))
    out.append(T(r"\subsection*{5. Verification of the MCAR simulation}", r"\subsection*{5. Vérification de la simulation MCAR}", lang))
    out.append(T(
        f"Four tests were applied to each mask: (1) a chi-squared test of uniformity across districts; (2) a chi-squared test of uniformity over time, by year; (3) a two-sample Kolmogorov--Smirnov test comparing the standardised true values of masked and observed cells, the most direct test since under MCAR the two distributions must coincide; (4) Fisher exact tests of independence on all pairs of districts. A mask is called compliant when it passes tests 2 and 3 at the {num(ALPHA,2,lang)} level; tests 1 and 4 are descriptive (Table~S{t_mv}). For one-week gaps, {int(bt.n_fail)} of {int(bt.n)} tests failed against {num(bt.expected,1,lang)} expected (one-sided binomial test, $p$ = {pval(bt.p_value,lang)}). For four- and eight-week gaps, cell-level independence is violated by construction, which is what a block mechanism means, and the pass rates are descriptive. The chi-squared tests refer to a multinomial law, more variable than the masks, which remove a fixed number of cells without replacement; Table~S{t_pn} gives the distribution of the $p$-values simulated under the actual generator, against which the observed $p$-values are compared.",
        f"Quatre tests ont été appliqués à chaque masque : (1) un test du khi-deux d'uniformité entre districts ; (2) un test du khi-deux d'uniformité dans le temps, par année ; (3) un test de Kolmogorov--Smirnov à deux échantillons comparant les vraies valeurs standardisées des cellules masquées et observées, test le plus direct puisque, sous MCAR, les deux distributions doivent coïncider ; (4) des tests exacts de Fisher d'indépendance sur toutes les paires de districts. Un masque est dit conforme quand il passe les tests 2 et 3 au seuil de {num(ALPHA,2,lang)} ; les tests 1 et 4 sont descriptifs (tableau~S{t_mv}). Pour les lacunes d'une semaine, {int(bt.n_fail)} tests sur {int(bt.n)} ont échoué, contre {num(bt.expected,1,lang)} attendus (test binomial unilatéral, $p$ = {pval(bt.p_value,lang)}). Pour les lacunes de quatre et huit semaines, l'indépendance au niveau cellule est violée par construction, ce qui est le sens même d'un mécanisme par blocs, et les taux de réussite sont descriptifs. Les tests du khi-deux se réfèrent à une loi multinomiale, plus variable que les masques, qui retirent un nombre fixe de cellules sans remise ; le tableau~S{t_pn} donne la distribution des valeurs $p$ simulées sous le générateur réel, à laquelle les valeurs $p$ observées sont comparées.", lang))
    out.append(table_env(t_mv, T('Share of masks passing each MCAR test, by gap length.', 'Part des masques passant chaque test MCAR, par longueur de lacune.', lang),
                         'rrrrrrr', T(r"Gap & Masks & Uniformity & KS & Uniformity & Significant & Compliant \\ (weeks) & & over time & & across districts & Fisher pairs (mean) & masks \\",
                                      r"Lacune & Masques & Uniformité & KS & Uniformité & Paires de Fisher & Masques \\ (sem.) & & dans le temps & & entre districts & significatives (moy.) & conformes \\", lang),
                         "\n".join(rows), src(['output/metrics/mcar_validation.csv', 'output/metrics/mcar_uniformity_tests.csv'], lang)))
    out.append(table_env(t_pn, T('Mean $p$-values of the uniformity tests: simulated under the actual mask generator and observed, one-week gaps.',
                                 'Moyenne des valeurs $p$ des tests d\'uniformité : simulées sous le générateur réel des masques et observées, lacunes d\'une semaine.', lang),
                         'llrrrrrr', T(r"Test & Rate & Simulated & Mean $p$ & Observed & Mean $p$ & KS observed & KS observed \\ & (\%) & masks & simulated & masks & observed & vs simulated & vs uniform \\",
                                       r"Test & Taux & Masques & $p$ moyen & Masques & $p$ moyen & KS observé & KS observé \\ & (\%) & simulés & simulé & observés & observé & contre simulé & contre uniforme \\", lang),
                         rows_pn, src(['output/metrics/mcar_pvalue_null.csv'], lang)))

    # 6. mechanisms
    cal = rd(MMET, 'mar_strong_calibration.csv')
    con = rd(MMET, 'mar_strong_contamination.csv').iloc[0]
    dg = rd(MMET, 'mechanism_diagnostics.csv')
    t_cal, t_dg = nb.table('S_calib', 2), nb.table('S_mechdiag', 2)
    ret = cal[cal.retained].iloc[0]
    assert ret.cohen_d == cal.cohen_d.max() and not cal.target_reached.any()
    after = cal[cal.beta > ret.beta]
    assert (after.cohen_d < ret.cohen_d).all()
    half = (len(cal) + 1) // 2
    rows_cal = []
    for i in range(half):
        a = cal.iloc[i]
        cells = [num(a.beta,2,lang), num(a.cohen_d,3,lang) + (r'$^{*}$' if a.retained else '')]
        if i + half < len(cal):
            b = cal.iloc[i + half]
            cells += [num(b.beta,2,lang), num(b.cohen_d,3,lang) + (r'$^{*}$' if b.retained else '')]
        else:
            cells += ['', '']
        rows_cal.append(' & '.join(cells) + r' \\')
    agg = dg.groupby(['mechanism', 'gap_length']).agg(n=('rep', 'size'), d=('cohen_d', 'mean'), rainy=('pct_rainy', 'mean'),
                                                      ors=('or_season', 'mean')).reset_index()
    agg['o'] = agg.mechanism.map({'MCAR': 0, 'MAR': 1, 'MAR_strong': 2, 'MNAR': 3})
    agg = agg.sort_values(['gap_length', 'o'])
    rows_dg = "\n".join(f"{MECH[r.mechanism][0 if lang=='en' else 1]} & {int(r.gap_length)} & {int(r.n)} & {num(r.d,3,lang)} & {pct(r.rainy,1,lang)} & {num(r.ors,2,lang)} \\\\" for _, r in agg.iterrows())
    hm = rd(MMET, 'hyperparameters_mechanism.csv')
    out.append(T(r"\subsection*{6. MAR, strong MAR and MNAR mechanisms}", r"\subsection*{6. Mécanismes MAR, MAR renforcé et MNAR}", lang))
    out.append(T(
        f"The reduced mechanism design uses 10\\% missing, gaps of one and eight weeks and {int(agg.n.max())} repetitions; its MCAR arm reuses the first {int(agg.n.max())} repetitions of the main design at 10\\%. MAR, strong MAR and MNAR masks were drawn with the seeds 500,000, 700,000 and 900,000 + 1,000 $\\times$ rep + rate + 7 $\\times$ gap. MAR and MNAR masks were drawn with propensity weights by a calibrated sampler subject to the same constraints as the MCAR masks; the strong MAR mechanism requires at least {MIN_OBS_WEEK_MARS} districts observed in each week, because stronger selection on the mean of the other districts tends to empty whole weeks. Its intensity $\\beta$ was calibrated on a grid to approach the selection strength of the MNAR mechanism, measured by Cohen's $d$ between masked and observed true values (Table~S{t_cal}): $d$ reached at most {num(ret.cohen_d,3,lang)} at $\\beta$ = {num(ret.beta,2,lang)}, below the MNAR target of {num(ret.target_mnar,3,lang)}, and decreased for stronger intensities; the retained intensity is this maximum. The conditioning variable is itself affected by missingness: {pct(con.pct_unavailable_neighbours,1,lang)} of the values of the other districts are unavailable at the moment of conditioning, and the correlation between their true and observable values is {num(con.cor_true_vs_observable_neighbours,3,lang)}. Table~S{t_dg} summarises the diagnostics of each mechanism.",
        f"Le plan réduit des mécanismes comporte 10~\\% de données manquantes, des lacunes d'une et huit semaines et {int(agg.n.max())} répétitions ; son volet MCAR reprend les {int(agg.n.max())} premières répétitions du plan principal à 10~\\%. Les masques MAR, MAR renforcé et MNAR ont été tirés avec les graines 500\\,000, 700\\,000 et 900\\,000 + 1\\,000 $\\times$ rép. + taux + 7 $\\times$ lacune. Les masques MAR et MNAR ont été tirés par un échantillonneur calibré à partir de pondérations de propension, soumis aux mêmes contraintes que les masques MCAR ; le MAR renforcé impose au moins {MIN_OBS_WEEK_MARS} districts observés chaque semaine, parce qu'une sélection plus forte sur la moyenne des autres districts tend à vider des semaines entières. Son intensité $\\beta$ a été calibrée sur une grille pour approcher la force de sélection du mécanisme MNAR, mesurée par le $d$ de Cohen entre vraies valeurs masquées et observées (tableau~S{t_cal}) : $d$ a atteint au plus {num(ret.cohen_d,3,lang)} à $\\beta$ = {num(ret.beta,2,lang)}, sous la cible MNAR de {num(ret.target_mnar,3,lang)}, puis a décru pour des intensités plus fortes ; l'intensité retenue est ce maximum. La variable de conditionnement est elle-même affectée par l'absence de données : {pct(con.pct_unavailable_neighbours,1,lang)} des valeurs des autres districts sont indisponibles au moment du conditionnement, et la corrélation entre leurs valeurs vraies et observables est de {num(con.cor_true_vs_observable_neighbours,3,lang)}. Le tableau~S{t_dg} résume les diagnostics de chaque mécanisme.", lang))
    out.append(table_env(t_cal, T('Calibration of the strong MAR mechanism: Cohen\'s $d$ by intensity $\\beta$.', 'Calibration du MAR renforcé : $d$ de Cohen selon l\'intensité $\\beta$.', lang),
                         'rrrr', r"$\beta$ & $d$ & $\beta$ & $d$ \\", "\n".join(rows_cal),
                         T(r"$^{*}$ Retained intensity. ", r"$^{*}$ Intensité retenue. ", lang) + src(['output_mechanism/metrics/mar_strong_calibration.csv'], lang)))
    out.append(table_env(t_dg, T('Diagnostics of the four mechanisms (means over repetitions).', 'Diagnostics des quatre mécanismes (moyennes sur les répétitions).', lang),
                         'lrrrrr', T(r"Mechanism & Gap & Reps & Cohen's $d$ & Masked weeks & Odds ratio \\ & (weeks) & & & in rainy season & (rainy season) \\",
                                     r"Mécanisme & Lacune & Rép. & $d$ de Cohen & Semaines masquées & Rapport de cotes \\ & (sem.) & & & en saison des pluies & (saison des pluies) \\", lang),
                         rows_dg, src(['output_mechanism/metrics/mechanism_diagnostics.csv', 'output_mechanism/metrics/mar_strong_contamination.csv'], lang)))

    # 7. Fourier, Kalman, negatives
    kf = rd(MET, 'kalman_fallback_check.csv').set_index('arm')
    assert kf.n_fallback.sum() == 0
    neg = ML[ML.n_negative > 0]
    rf = rd(MET, 'forecast_refit_counts.csv').set_index('scope')
    neg_methods = neg.method.unique().tolist()
    out.append(T(r"\subsection*{7. Implementation details}", r"\subsection*{7. Détails d'implémentation}", lang))
    out.append(T(
        f"\\textit{{Fourier terms.}} The annual and semi-annual Fourier terms were coded on the day of the year divided by 365.25 rather than on the ISO week: the study period contains {['no', 'one', 'two'][len(ISO53)]} ISO week 53 (the week ending {ISO53[0].date()}), which would overflow a division by 52 and create a discontinuity, whereas the day-of-year coding is bounded and absorbs the calendar drift between years.\n\n"
        f"\\textit{{Kalman fallback.}} The fallback cascade of Kalman smoothing (\\code{{auto.arima}}, then linear interpolation) was never triggered: a replay of the first level on every archived mask gave {int(kf.loc['main','n_fallback'])} failures in {num(kf.loc['main','n_series'],0,lang)} series of the main design ({int(kf.loc['main','n_masks'])} masks) and {int(kf.loc['mechanism','n_fallback'])} in {num(kf.loc['mechanism','n_series'],0,lang)} series of the reduced mechanism design ({int(kf.loc['mechanism','n_masks'])} masks).\n\n"
        f"\\textit{{Negative imputations.}} Negative imputed values were counted and set to zero before the metrics were computed. At least one negative value occurred in {len(neg)} of the {num(N_SCEN,0,lang)} scenarios ({', '.join(f'{int((neg.gap_length==g).sum())} at {g} week' + ('s' if g > 1 else '') for g in sorted(neg.gap_length.unique()))}), all under {', '.join(mname(m,lang) for m in neg_methods)}, that is {int(neg.n_negative.sum())} cells in total.\n\n"
        f"\\textit{{Forecasting refits.}} With the ARIMA orders fixed on the reference, {'no fit had to be reselected and no origin was skipped' if rf.n_fit_fallback_auto_arima.sum() == 0 and rf.n_origins_skipped.sum() == 0 else f'{int(rf.n_fit_fallback_auto_arima.sum())} fits were reselected and {int(rf.n_origins_skipped.sum())} origins skipped'} ({num(rf.loc['imputed','n_series'],0,lang)} imputed series and {int(rf.loc['reference','n_series'])} reference series).",
        f"\\textit{{Termes de Fourier.}} Les termes de Fourier annuels et semi-annuels ont été codés sur le jour de l'année divisé par 365,25 plutôt que sur la semaine ISO : la période d'étude contient {['aucune', 'une', 'deux'][len(ISO53)]} semaine ISO 53 (la semaine finissant le {ISO53[0].date()}), qui déborderait d'une division par 52 et créerait une discontinuité, alors que le codage sur le jour de l'année est borné et absorbe la dérive calendaire d'une année à l'autre.\n\n"
        f"\\textit{{Repli du lissage de Kalman.}} La cascade de repli du lissage de Kalman (\\code{{auto.arima}}, puis interpolation linéaire) n'a jamais été déclenchée : un rejeu du premier niveau sur tous les masques archivés a donné {int(kf.loc['main','n_fallback'])} échec sur {num(kf.loc['main','n_series'],0,lang)} séries du plan principal ({int(kf.loc['main','n_masks'])} masques) et {int(kf.loc['mechanism','n_fallback'])} sur {num(kf.loc['mechanism','n_series'],0,lang)} séries du plan réduit des mécanismes ({int(kf.loc['mechanism','n_masks'])} masques).\n\n"
        f"\\textit{{Imputations négatives.}} Les valeurs imputées négatives ont été comptées puis ramenées à zéro avant le calcul des métriques. Au moins une valeur négative est apparue dans {len(neg)} des {num(N_SCEN,0,lang)} scénarios ({', '.join(f'{int((neg.gap_length==g).sum())} à {g} semaine' + ('s' if g > 1 else '') for g in sorted(neg.gap_length.unique()))}), tous sous {', '.join(mname(m,lang) for m in neg_methods)}, soit {int(neg.n_negative.sum())} cellules au total.\n\n"
        f"\\textit{{Réajustements de la prévision.}} Avec les ordres ARIMA fixés sur la référence, {'aucun ajustement n’a dû être resélectionné et aucune origine n’a été sautée' if rf.n_fit_fallback_auto_arima.sum() == 0 and rf.n_origins_skipped.sum() == 0 else f'{int(rf.n_fit_fallback_auto_arima.sum())} ajustements ont été resélectionnés et {int(rf.n_origins_skipped.sum())} origines sautées'} ({num(rf.loc['imputed','n_series'],0,lang)} séries imputées et {int(rf.loc['reference','n_series'])} séries de référence).", lang))

    # 8. k tuning and seeds
    hp = rd(MET, 'hyperparameters.csv')
    tuned = hp[hp.tuned]
    assert (tuned.groupby(['missing_rate', 'gap_length']).size() == K_TUNED_REPS_MAIN).all()
    t_k = nb.table('S_k', 2)
    rows = []
    for (r_, g), d in hp.groupby(['missing_rate', 'gap_length']):
        tv = d[d.tuned].value.value_counts().sort_index()
        mode = d[~d.tuned].value.unique()
        assert len(mode) == 1
        rows.append(f"{num(r_,0,lang)} & {int(g)} & " + ', '.join(f"{int(k)} ({int(c)})" for k, c in tv.items()) + f" & {int(mode[0])} \\\\")
    hmm = hm.groupby(['mechanism', 'gap_length']).value.agg(lambda s: s.mode().iloc[0]).reset_index()
    mech_k = T('; ', ' ; ', lang).join(f"{MECH[r.mechanism][0 if lang=='en' else 1]}, {int(r.gap_length)} {T('wk','sem.',lang)}{T(':',' :',lang)} {int(r.value)}" for _, r in hmm.iterrows())
    out.append(T(r"\subsection*{8. Tuning of $k$ for KNN, and seeds}", r"\subsection*{8. Réglage de $k$ pour le KNN, et graines}", lang))
    out.append(T(
        f"$k$ was chosen on the grid \\{{{', '.join(map(str, K_GRID))}\\}} by internal re-masking of observed cells ({K_ROUNDS_MAIN} rounds), on the first {K_TUNED_REPS_MAIN} repetitions of each configuration; the modal value was reused for the other repetitions (Table~S{t_k}). Reduced mechanism design, modal $k$: {mech_k}; strong MAR: $k$ tuned by the same rule, its value not recorded by \\code{{R/07\\_mar\\_strong\\_arm.R}}. Seeds: masks \\code{{{SEED_MASK}}}; re-masking rounds \\code{{{SEED_TUNING}}}; \\code{{mice}} and \\code{{missRanger}} \\code{{seed = {SEED_MICE}}}.",
        f"$k$ a été choisi sur la grille \\{{{', '.join(map(str, K_GRID))}\\}} par re-masquage interne de cellules observées ({K_ROUNDS_MAIN} tours), sur les {K_TUNED_REPS_MAIN} premières répétitions de chaque configuration ; la valeur modale a été reprise pour les autres répétitions (tableau~S{t_k}). Plan réduit des mécanismes, $k$ modal : {mech_k} ; MAR renforcé : $k$ réglé selon la même règle, valeur non enregistrée par \\code{{R/07\\_mar\\_strong\\_arm.R}}. Graines : masques \\code{{{SEED_MASK}}} ; tours de re-masquage \\code{{{SEED_TUNING}}} ; \\code{{mice}} et \\code{{missRanger}} \\code{{seed = {SEED_MICE}}}.", lang))
    out.append(table_env(t_k, T('Values of $k$ selected on the tuned repetitions (count in brackets) and modal value reused.', 'Valeurs de $k$ choisies sur les répétitions réglées (effectif entre parenthèses) et valeur modale reprise.', lang),
                         'rrlr', T(r"Rate (\%) & Gap (weeks) & Tuned repetitions & Reused value \\", r"Taux (\%) & Lacune (sem.) & Répétitions réglées & Valeur reprise \\", lang),
                         "\n".join(rows), src(['output/metrics/hyperparameters.csv', 'output_mechanism/metrics/hyperparameters_mechanism.csv'], lang)))
    return "\n\n".join(out) + "\n"


# ================================================================== AF3
BELEL_FR = {'Linear interpolation (RETAINED)': 'Interpolation linéaire (74,5, arrondie à 74 : valeur retenue)', 'Seasonal decomposition': 'Décomposition saisonnière',
            'MissForest + period': 'MissForest + covariables de période', 'MissForest': 'MissForest',
            'MICE deterministic': 'MICE, régression déterministe', 'Annual mean (source value)': 'Moyenne annuelle (valeur du fichier source)'}
BELEL_EN = {'Linear interpolation (RETAINED)': 'Linear interpolation (74.5, rounded to 74: retained value)', 'MissForest + period': 'MissForest + period covariates',
            'MICE deterministic': 'MICE, deterministic regression', 'Annual mean (source value)': 'Annual mean (value in the source file)'}


def belel_label(m, lang):
    if m.startswith('KNN'):
        k = re.search(r'k\s*=\s*(\d+)', m).group(1)
        return f"KNN ($k$ = {k})"
    return (BELEL_EN if lang == 'en' else BELEL_FR).get(m, m)


def af3(lang, nb):
    bs = rd(DER, 'reference_belel_sensitivity.csv')
    fl = rd(DER, 'reference_flagged_cells.csv').iloc[0]
    t = nb.table('S_belel', 3)
    rows = "\n".join(f"{belel_label(r.method,lang)} & {num(r.estimate,1,lang)} & {num(r.difference_vs_retained,1,lang,sign=True) if r.difference_vs_retained != 0 else '0'} \\\\" for _, r in bs.iterrows())
    near = bs[bs.difference_vs_retained.abs() <= 15]
    far = bs[bs.difference_vs_retained.abs() > 15]
    ncell = N_WEEKS * N_DIS
    # built outside the f-strings: Python 3.10 forbids the enclosing quote inside an f-string expression
    exc_en = ' and '.join('``' + belel_label(r.method, lang) + "''" + ' (' + num(r.estimate, 1, lang) + ')' for _, r in far.iterrows())
    exc_fr = ' et '.join('« ' + belel_label(r.method, lang) + ' » (' + num(r.estimate, 1, lang) + ')' for _, r in far.iterrows())
    body = T(
        f"\\section*{{Additional file 3. Sensitivity analysis of the Belel cell}}\n\nThe reference series contains one cell identified as never observed by the check for imputations made upstream (Additional file 2): {fl.district}, week ending {fl.periodid}. The source file stores {num(fl.source_value,3,lang)}, the 2019 annual mean of the district, filled in upstream of this study; the adjacent weeks record 79 and 70 cases. The value was replaced by {int(fl.retained_value)} ({fl.replacement_rule.replace('(79+70)/2','(79 + 70)/2')}), a rule fixed before the benchmark was run, and the cell is excluded from every error metric; it remains a predictor for other cells and part of the reference series used for forecasting. Table~S{t} compares seven candidate values, each obtained by setting the cell to missing and imputing it with the method named. {['None','One','Two','Three','Four','Five','Six','Seven'][len(near)]} of the seven fall within 15 cases of the linear interpolation; the exceptions are {exc_en}. Because the cell is excluded from the metrics, its only influence is as a predictor: one cell out of {num(ncell,0,lang)}, or {pct(100/ncell,3,lang)} of the reference matrix.\n\n",
        f"\\section*{{Fichier additionnel 3. Analyse de sensibilité de la cellule de Belel}}\n\nLa série de référence contient une cellule identifiée comme non observée par le contrôle des imputations faites en amont (fichier additionnel 2) : {fl.district}, semaine finissant le {fl.periodid}. Le fichier source y enregistre {num(fl.source_value,3,lang)}, la moyenne annuelle 2019 du district, renseignée en amont de cette étude ; les semaines adjacentes relèvent 79 et 70 cas. La valeur a été remplacée par {int(fl.retained_value)} (interpolation linéaire entre les semaines adjacentes, (79 + 70)/2 = 74,5, arrondie), règle fixée avant l'exécution de l'étude, et la cellule est exclue de toutes les métriques d'erreur ; elle reste un prédicteur des autres cellules et fait partie de la série de référence utilisée pour la prévision. Le tableau~S{t} compare sept valeurs candidates, chacune obtenue en remettant la cellule à manquante puis en l'imputant par la méthode indiquée. {['Aucune','Une','Deux','Trois','Quatre','Cinq','Six','Sept'][len(near)]} des sept se situent à moins de 15 cas de l'interpolation linéaire ; les exceptions sont {exc_fr}. La cellule étant exclue des métriques, sa seule influence est celle d'un prédicteur : une cellule sur {num(ncell,0,lang)}, soit {pct(100/ncell,3,lang)} de la matrice de référence.\n\n", lang)
    return body + table_env(t, T(f'Candidate values for the Belel cell (week ending {fl.periodid}), in confirmed cases.', f'Valeurs candidates pour la cellule de Belel (semaine finissant le {fl.periodid}), en cas confirmés.', lang),
                            'lrr', T(r"Method & Estimate & Difference from linear interpolation \\", r"Méthode & Estimation & Écart à l'interpolation linéaire \\", lang),
                            rows, src(['data/derived/reference_belel_sensitivity.csv', 'data/derived/reference_flagged_cells.csv'], lang))


# ================================================================== AF4
PKG_ROLE = {  # package -> (EN role, FR role); roles are descriptions, versions are read from the CSV
    'mice': ('MICE-pmm and MICE-norm.predict', 'MICE-pmm et MICE-norm.predict'),
    'missRanger': ('MissForest and MissForest-ST', 'MissForest et MissForest-ST'),
    'ranger': ('Random forests used by missRanger', 'Forêts aléatoires utilisées par missRanger'),
    'VIM': ('KNN imputation', 'Imputation par KNN'),
    'imputeTS': ('Kalman smoothing, linear interpolation, seasonal decomposition', 'Lissage de Kalman, interpolation linéaire, décomposition saisonnière'),
    'forecast': ('Forecasting analysis (Fourier regression with ARIMA errors)', 'Analyse de prévision (régression de Fourier à erreurs ARIMA)'),
    'PMCMRplus': ('Nemenyi post hoc test', 'Test post hoc de Nemenyi'),
}


def af4(lang, nb):
    pv = rd(DOCS, 'package_versions.csv')
    env = open(os.path.join(DOCS, 'ENVIRONMENT.md'), encoding='utf-8').read()
    def envrow(key):
        m = re.search(r'\|\s*' + re.escape(key) + r'\s*\|\s*([^|\n]*)\|', env)
        return m.group(1).strip() if m else None
    date = re.search(r'on (\d{4}-\d{2}-\d{2})', env).group(1)
    import matplotlib
    t1, t2 = nb.table('S_system', 4), nb.table('S_packages', 4)
    platform_tex = envrow('Platform').replace('_', '\\_')  # outside the f-string (Python 3.10)
    sysrows = "\n".join([
        f"R & {envrow('R version').replace('R version ', '')} \\\\",
        f"{T('Platform','Plateforme',lang)} & {platform_tex} \\\\",
        f"{T('Operating system','Système',lang)} & {envrow('Running under')} \\\\",
        f"Python ({T('figures and additional files','figures et fichiers additionnels',lang)}) & {platform.python_version()}, matplotlib {matplotlib.__version__}, pandas {pd.__version__}, numpy {np.__version__} \\\\"])
    main = pv[pv.package.isin(PKG_ROLE)]
    other = pv[~pv.package.isin(PKG_ROLE)]
    rows = "\n".join(f"{r.package} {r.version} & {PKG_ROLE[r.package][0 if lang=='en' else 1]} \\\\" for _, r in main.iterrows())
    rows += "\n" + T('Other packages', 'Autres paquets', lang) + " & " + ', '.join(f"{r.package} {r.version}" for _, r in other.iterrows()) + r" \\"
    head = T(f"\\section*{{Additional file 4. Software environment}}\n\nAll analyses were run in R; the figures and the additional files were produced in Python from the analysis outputs. The R versions were recorded by \\code{{R/99\\_session\\_info.R}} on {date}; the Python versions are those of the interpreter that built this file.\n\n",
             f"\\section*{{Fichier additionnel 4. Environnement logiciel}}\n\nToutes les analyses ont été exécutées sous R ; les figures et les fichiers additionnels ont été produits en Python à partir des sorties de l'analyse. Les versions de R ont été enregistrées par \\code{{R/99\\_session\\_info.R}} le {date} ; les versions de Python sont celles de l'interpréteur qui a produit ce fichier.\n\n", lang)
    return (head + table_env(t1, T('System and language versions.', 'Versions du système et des langages.', lang), 'lp{0.62\\textwidth}',
                             T(r"Item & Value \\", r"Élément & Valeur \\", lang), sysrows, src(['docs/ENVIRONMENT.md'], lang))
            + table_env(t2, T('R packages and their role in the study.', 'Paquets R et leur rôle dans l\'étude.', lang), 'p{0.40\\textwidth}p{0.55\\textwidth}',
                        T(r"Package and version & Role \\", r"Paquet et version & Rôle \\", lang), rows, src(['docs/package_versions.csv'], lang)))


# ================================================================== AF5
def af5(lang, nb):
    pe = rd(MET, 'period_effect.csv')
    st = rd(MET, 'district_spearman_tests.csv')
    s = st[(st.outcome == 'gain_MissForest_pct') & (st.characteristic == 'mean_corr_other_districts')].iloc[0]
    # guard for the sentence of the S1 caption: for the cross-sectional methods, the seasonal share
    # shrinks between one- and eight-week gaps while the trend share stays positive
    cs = ['KNN', 'MICE_deterministic', 'MICE_inference', 'MICE_precision', 'MissForest']
    m = pe.groupby(['method', 'gap_length'])[['gain_seasonal_pct', 'gain_trend_pct']].mean()
    for x in cs:
        assert m.loc[(x, 8), 'gain_seasonal_pct'] < m.loc[(x, 1), 'gain_seasonal_pct']
        assert m.loc[(x, 8), 'gain_trend_pct'] > 0
    f1, f2 = nb.figure('S_period', 5), nb.figure('S_districts', 5)
    sfx = '' if lang == 'en' else '_fr'
    cap1 = T(r"Where the gain from period covariates comes from. Gain in mean absolute error from adding period covariates to each method that accepts covariates, split into the part due to the seasonal terms (\code{NoTime} to \code{Seasonal}) and the part due to the time index (\code{Seasonal} to \code{SeasonalTrend}), as a percentage of the \code{NoTime} error, averaged over the three missingness rates. (a) One-week gaps; (b) eight-week gaps. For the cross-sectional methods (KNN, MICE, MissForest), the seasonal share shrinks between one- and eight-week gaps while the trend share remains. Mean imputation and the three temporal methods take no covariates and are not shown. ",
             r"D'où vient le gain des covariables de période. Gain d'erreur absolue moyenne obtenu en ajoutant les covariables de période à chaque méthode qui en accepte, décomposé en une part due aux termes saisonniers (\code{NoTime} vers \code{Seasonal}) et une part due à l'index temporel (\code{Seasonal} vers \code{SeasonalTrend}), en pourcentage de l'erreur sous \code{NoTime}, moyenné sur les trois taux de données manquantes. (a) Lacunes d'une semaine ; (b) lacunes de huit semaines. Pour les méthodes transversales (KNN, MICE, MissForest), la part saisonnière se réduit entre les lacunes d'une et de huit semaines, tandis que la part de la tendance demeure. L'imputation par la moyenne et les trois méthodes temporelles n'acceptent aucune covariable et ne figurent pas. ", lang) + src(['output/metrics/period_effect.csv'], lang)
    cap2 = T(f"Gain of MissForest over mean imputation, by district. Percentage reduction in mean absolute error of MissForest relative to mean imputation in each of the eleven districts, one-week gaps, against the district's mean correlation with the other ten. Spearman $\\rho$ = {num(s.rho,2,lang,sign=True)} ($p$ = {pval(s.p_value,lang)}, $n$ = {int(s.n)}), above the Bonferroni threshold of {num(s.bonferroni_threshold,5,lang)} for the eight district-level tests. With eleven units the analysis is exploratory. ",
             f"Gain de MissForest sur l'imputation par la moyenne, par district. Réduction en pourcentage de l'erreur absolue moyenne de MissForest par rapport à l'imputation par la moyenne dans chacun des onze districts, lacunes d'une semaine, en fonction de la corrélation moyenne du district avec les dix autres. $\\rho$ de Spearman = {num(s.rho,2,lang,sign=True)} ($p$ = {pval(s.p_value,lang)}, $n$ = {int(s.n)}), au-dessus du seuil de Bonferroni de {num(s.bonferroni_threshold,5,lang)} pour les huit tests au niveau district. Avec onze unités, l'analyse est exploratoire. ", lang) + src(['output/metrics/gain_by_district.csv', 'output/metrics/district_spearman_tests.csv'], lang)
    assert s.p_value > s.bonferroni_threshold
    def fig(n, file, width, cap):
        return (r"\begin{figure}[htbp]" + "\n" + r"\setcounter{figure}{%d}" % (n - 1) + "\n\\centering\n"
                + r"\includegraphics[width=%s\textwidth]{%s}" % (width, file) + "\n" + r"\caption{%s}" % cap + "\n" + r"\end{figure}" + "\n")
    head = T("\\section*{Additional file 5. Supplementary figures}\n\nTwo figures supporting statements of the Results, drawn by \\code{redaction/figures/make\\_figures.py} from the outputs named in each legend.\n\n",
             "\\section*{Fichier additionnel 5. Figures supplémentaires}\n\nDeux figures à l'appui d'énoncés des Résultats, tracées par \\code{redaction/figures/make\\_figures.py} à partir des sorties citées dans chaque légende.\n\n", lang)
    return head + fig(f1, f'S5_figS1_period_effect{sfx}.pdf', '1', cap1) + fig(f2, f'S5_figS2_districts{sfx}.pdf', '0.8', cap2)


# ================================================================== AF6
def af6(lang, nb):
    out = [T(r"\section*{Additional file 6. Supplementary results}", r"\section*{Fichier additionnel 6. Résultats complémentaires}", lang),
           T("Tables supporting the Results of the main text. Unless stated otherwise, each method is scored under its retained predictor block, the block with the lowest mean absolute error.",
             "Tableaux à l'appui des Résultats du texte principal. Sauf mention contraire, chaque méthode est évaluée sous son bloc de prédicteurs retenu, celui de plus faible erreur absolue moyenne.", lang)]
    order = rd(MET, 'friedman_ranks_main.csv').method.tolist() if os.path.exists(os.path.join(MET, 'friedman_ranks_main.csv')) else list(METHOD)

    # 1. six metrics, one-week gaps
    d = ML[ML.gap_length == 1].merge(SEL, on=['method', 'variant'])
    agg = d.groupby(['method', 'variant', 'missing_rate'])[['MAE', 'RMSE', 'MAPE', 'bias', 'var_ratio', 'R2']].mean().reset_index()
    chk = rd(MET, 'table_full_supplement.csv').merge(agg, on=['method', 'variant', 'missing_rate'])
    assert len(chk) == 30 and np.allclose(chk.MAE_m, chk.MAE) and np.allclose(chk.RMSE_m, chk.RMSE)
    t6 = nb.table('S_six', 6)
    rows = []
    for m in order:
        for _, r in agg[agg.method == m].sort_values('missing_rate').iterrows():
            rows.append(f"{mname(m,lang) if r.missing_rate == agg.missing_rate.min() else ''} & {num(r.missing_rate,0,lang)} & {num(r.MAE,1,lang)} & {num(r.RMSE,1,lang)} & {num(r.MAPE,1,lang)} & {num(r.bias,1,lang)} & {num(r.var_ratio,3,lang)} & {num(r.R2,3,lang)} \\\\")
        rows.append(r"\addlinespace[1pt]")
    out.append(T(r"\subsection*{1. Six metrics, one-week gaps}", r"\subsection*{1. Six métriques, lacunes d'une semaine}", lang))
    out.append(table_env(t6, T('Six accuracy and fidelity metrics by method and missingness rate, one-week gaps (means over 20 repetitions).', 'Six métriques de précision et de fidélité par méthode et taux de données manquantes, lacunes d\'une semaine (moyennes sur 20 répétitions).', lang),
                         'lrrrrrrr', T(r"Method & Rate (\%) & MAE & RMSE & MAPE (\%) & Bias & Variance ratio & $R^2$ \\", r"Méthode & Taux (\%) & MAE & RMSE & MAPE (\%) & Biais & Ratio de variance & $R^2$ \\", lang),
                         "\n".join(rows[:-1]),
                         T("Variance ratio and $R^2$ are computed over the masked cells of the eleven districts pooled. ", "Le ratio de variance et le $R^2$ sont calculés sur les cellules masquées des onze districts réunis. ", lang) + src(['output/metrics/metrics_long.csv', 'output/metrics/selected_variant.csv'], lang)))

    # 2. Friedman and Nemenyi by gap length
    fb = rd(MET, 'friedman_by_gap.csv').set_index('gap_length')
    fr = rd(MET, 'friedman_ranks_by_gap.csv')
    ne = rd(MET, 'nemenyi_pairs_by_gap.csv')
    t_fr, t_ne = nb.table('S_friedman_gap', 6), nb.table('S_nemenyi_gap', 6)
    piv = fr.pivot(index='method', columns='gap_length', values='mean_rank')
    piv = piv.loc[piv[1].sort_values().index]
    rows = "\n".join(f"{mname(m,lang)} & " + ' & '.join(num(piv.loc[m, g], 2, lang) for g in [1, 4, 8]) + r" \\" for m in piv.index)
    rows += "\n\\midrule\n" + "$\\chi^2$ (" + T('9 df', '9 ddl', lang) + ") & " + ' & '.join(num(fb.loc[g, 'chi_squared'], 1, lang) for g in [1, 4, 8]) + r" \\"
    rows += "\n$p$ & " + ' & '.join(pval(fb.loc[g, 'p_value'], lang) for g in [1, 4, 8]) + r" \\"
    rows += "\n" + T('Critical difference', 'Différence critique', lang) + " & " + ' & '.join(num(fb.loc[g, 'cd'], 2, lang) for g in [1, 4, 8]) + r" \\"
    out.append(T(r"\subsection*{2. Friedman and Nemenyi tests within each gap length}", r"\subsection*{2. Tests de Friedman et de Nemenyi à chaque longueur de lacune}", lang))
    out.append(table_env(t_fr, T('Mean Friedman rank of the ten methods over the 60 blocks (rate $\\times$ repetition), by gap length.', 'Rang moyen de Friedman des dix méthodes sur les 60 blocs (taux $\\times$ répétition), par longueur de lacune.', lang),
                         'lrrr', T(r"Method & 1 week & 4 weeks & 8 weeks \\", r"Méthode & 1 semaine & 4 semaines & 8 semaines \\", lang), rows,
                         src(['output/metrics/friedman_by_gap.csv', 'output/metrics/friedman_ranks_by_gap.csv'], lang)))
    rows = []
    for g in [4, 8]:
        top = fr[fr.gap_length == g].nsmallest(5, 'mean_rank').method.tolist()
        sub = ne[(ne.gap_length == g) & ne.method_a.isin(top) & ne.method_b.isin(top)].copy()
        sub['key'] = sub.apply(lambda r: min(top.index(r.method_a), top.index(r.method_b)) * 10 + max(top.index(r.method_a), top.index(r.method_b)), axis=1)
        assert len(sub) == 10
        for _, r in sub.sort_values('key').iterrows():
            a, b = sorted([r.method_a, r.method_b], key=top.index)
            rows.append(f"{g} & {mname(a,lang)} & {mname(b,lang)} & {num(r.rank_diff,2,lang)} & {pval(r.p_nemenyi,lang)} & {T('yes','oui',lang) if r.exceeds_cd else T('no','non',lang)} \\\\")
        rows.append(r"\addlinespace[2pt]")
    out.append(table_env(t_ne, T('Nemenyi comparisons between the five leading methods at four and eight weeks.', 'Comparaisons de Nemenyi entre les cinq premières méthodes à quatre et huit semaines.', lang),
                         'rllrrr', T(r"Gap & Method A & Method B & Rank difference & $p$ & Exceeds CD \\", r"Lacune & Méthode A & Méthode B & Écart de rang & $p$ & Dépasse la DC \\", lang),
                         "\n".join(rows[:-1]), src(['output/metrics/nemenyi_pairs_by_gap.csv'], lang)))

    # 3. rate versus gap length (A1)
    ag = rd(MET, 'rate_vs_gap_agreement.csv')
    it = rd(MET, 'rate_vs_gap_interaction.csv').set_index('term')
    t3 = rd(MET, 'rate_vs_gap_top3.csv')
    t_ag, t_it, t_t3 = nb.table('S_excess', 6), nb.table('S_interaction', 6), nb.table('S_top3', 6)
    rows = []
    for fac, lab in [('gap', T('Gap length', 'Longueur', lang)), ('rate', T('Rate', 'Taux', lang))]:
        sub = ag[ag.factor == fac]
        for _, r in sub.iterrows():
            fixed = (f"{num(r.fixed_level,0,lang)}~\\%" if fac == 'gap' else f"{int(r.fixed_level)} {T('wk','sem.',lang)}")
            lv = (f"{int(r.level_a)}--{int(r.level_b)} {T('wk','sem.',lang)}" if fac == 'gap' else f"{int(r.level_a)}--{int(r.level_b)}~\\%")
            rows.append(f"{lab} & {fixed} & {lv} & {num(r.method_excess,2,lang)} {ci(r.method_excess_lo, r.method_excess_hi, 2, lang)} & {num(r.combo_excess,2,lang)} {ci(r.combo_excess_lo, r.combo_excess_hi, 2, lang)} & {int(r.top3_overlap)}/3 & {num(r.spearman_24,3,lang)} {ci(r.spearman_24_lo, r.spearman_24_hi, 3, lang)} \\\\")
        rows.append(r"\midrule")
    out.append(T(r"\subsection*{3. Gap length against missingness rate}", r"\subsection*{3. Longueur des lacunes contre taux de données manquantes}", lang))
    out.append(T("The excess change of the winning method is the probability that two repetitions, one drawn in each condition, have different winners, minus the mean disagreement between two repetitions of the same condition (Gini--Simpson index, unbiased estimator); it is 0 when the two conditions have the same distribution of winners and 1 when each condition always has its own winner. It is computed on the ten methods (main criterion) and on the 24 method--predictor combinations. Confidence intervals: bootstrap of repetitions within conditions, 2,000 draws.",
                 "L'excès de changement de la méthode gagnante est la probabilité que deux répétitions, tirées l'une dans chaque condition, aient des gagnantes différentes, diminuée du désaccord moyen entre deux répétitions d'une même condition (indice de Gini--Simpson, estimateur sans biais) ; il vaut 0 quand les deux conditions ont la même répartition de gagnantes et 1 quand chacune a toujours sa propre gagnante. Il est calculé sur les dix méthodes (critère principal) et sur les 24 combinaisons méthode--prédicteurs. Intervalles de confiance : bootstrap des répétitions à l'intérieur des conditions, 2~000 tirages.", lang))
    out.append(table_env(t_ag, T('Excess change of the winning method, overlap of the three leading combinations and Spearman correlation of the 24 combinations, for each pair of levels of one factor, the other being fixed.',
                                 'Excès de changement de la méthode gagnante, recouvrement des trois premières combinaisons et corrélation de Spearman des 24 combinaisons, pour chaque paire de niveaux d\'un facteur, l\'autre étant fixé.', lang),
                         'lllllrl', T(r"Factor & Fixed at & Levels & Excess, 10 methods [95\% CI] & Excess, 24 combinations & Top 3 & Spearman $\rho$ \\", r"Facteur & Fixé à & Niveaux & Excès, 10 méthodes [IC 95~\%] & Excès, 24 combinaisons & 3 premières & $\rho$ de Spearman \\", lang),
                         "\n".join(rows[:-1]), src(['output/metrics/rate_vs_gap_agreement.csv'], lang), size='scriptsize'))
    # labels built outside the f-strings (Python 3.10: no backslash in an f-string expression)
    lab_gap = T('Method $\\times$ gap length', 'Méthode $\\times$ longueur', lang)
    lab_rate = T('Method $\\times$ rate', 'Méthode $\\times$ taux', lang)
    rows = "\n".join([
        f"{lab_gap} & {int(it.loc['method_x_gap','df'])} & {num(it.loc['method_x_gap','ss'],3,lang)} {ci(it.loc['method_x_gap','ci_lo'], it.loc['method_x_gap','ci_hi'],3,lang)} & {pct(100*it.loc['method_x_gap','share_of_total_ss'],1,lang)} \\\\",
        f"{lab_rate} & {int(it.loc['method_x_rate','df'])} & {num(it.loc['method_x_rate','ss'],3,lang)} {ci(it.loc['method_x_rate','ci_lo'], it.loc['method_x_rate','ci_hi'],3,lang)} & {pct(100*it.loc['method_x_rate','share_of_total_ss'],1,lang)} \\\\",
        f"{T('Ratio','Rapport',lang)} & & {num(it.loc['ratio_gap_over_rate','ss'],2,lang)} {ci(it.loc['ratio_gap_over_rate','ci_lo'], it.loc['ratio_gap_over_rate','ci_hi'],2,lang)} & \\\\"])
    out.append(table_env(t_it, T('Interaction sums of squares on log(MAE).', 'Sommes des carrés d\'interaction sur log(MAE).', lang), 'lrll',
                         T(r"Term & df & Sum of squares [95\% CI] & Share of total \\", r"Terme & ddl & Somme des carrés [IC 95~\%] & Part du total \\", lang), rows,
                         T("Table of the means of log(MAE) over the 20 repetitions for the 24 combinations, three rates and three gap lengths; sum of squares = 3 $\\times$ sum of squared interaction residuals; bootstrap of repetitions within cells, 2,000 draws. ",
                           "Tableau des moyennes de log(MAE) sur les 20 répétitions pour les 24 combinaisons, trois taux et trois longueurs ; somme des carrés = 3 $\\times$ somme des carrés des résidus d'interaction ; bootstrap des répétitions à l'intérieur des cellules, 2~000 tirages. ", lang) + src(['output/metrics/rate_vs_gap_interaction.csv'], lang)))
    def combo(s):
        m, v = s.strip().split('|')
        return f"{mname(m,lang)} ({v})"
    sep = T('; ', ' ; ', lang)  # French typography: space before the semicolon
    rows = "\n".join(f"{num(r.missing_rate,0,lang)} & {int(r.gap_length)} & {sep.join(combo(x) for x in r.top3.split(';'))} \\\\" for _, r in t3.iterrows())
    out.append(table_env(t_t3, T('Three leading method--predictor combinations by condition (lowest mean absolute error first).', 'Trois premières combinaisons méthode--prédicteurs par condition (plus faible erreur absolue moyenne d\'abord).', lang),
                         'rrl', T(r"Rate (\%) & Gap (weeks) & Combinations \\", r"Taux (\%) & Lacune (sem.) & Combinaisons \\", lang), rows, src(['output/metrics/rate_vs_gap_top3.csv'], lang), size='scriptsize'))

    # 4. mechanisms at eight weeks
    mr = rd(MMET, 'mechanism_ranks_long.csv')
    at = rd(MMET, 'mechanism_agreement_tests.csv')
    t_mr, t_at = nb.table('S_mech8', 6), nb.table('S_mechagree', 6)
    m8 = mr[mr.gap_length == 8]
    mechs = ['MCAR', 'MAR', 'MAR_strong', 'MNAR']
    ordm = m8[m8.mechanism == 'MCAR'].sort_values('mean_rank').method.tolist()
    rows = []
    for m in ordm:
        cells = []
        for k in mechs:
            r = m8[(m8.mechanism == k) & (m8.method == m)].iloc[0]
            cells.append(f"{num(r.mean_rank,1,lang)} & {num(r.bias,1,lang)}")
        rows.append(f"{mname(m,lang)} & " + ' & '.join(cells) + r" \\")
    cd = m8.cd_reduced.iloc[0]
    out.append(T(r"\subsection*{4. Reduced mechanism design, eight-week gaps}", r"\subsection*{4. Plan réduit des mécanismes, lacunes de huit semaines}", lang))
    out.append(table_env(t_mr, T(f'Mean rank and mean bias (cases per week) of each method under the four mechanisms, eight-week gaps (reduced design: 10\\% missing, {int(m8.n_reps.max())} repetitions).',
                                 f'Rang moyen et biais moyen (cas par semaine) de chaque méthode sous les quatre mécanismes, lacunes de huit semaines (plan réduit : 10~\\% de données manquantes, {int(m8.n_reps.max())} répétitions).', lang),
                         'lrrrrrrrr', ' & ' + ' & '.join(r"\multicolumn{2}{c}{%s}" % MECH[k][0 if lang == 'en' else 1] for k in mechs) + r" \\" + "\n" + T('Method', 'Méthode', lang) + ' & ' + ' & '.join([T('Rank & Bias', 'Rang & Biais', lang)] * 4) + r" \\",
                         "\n".join(rows), T(f"Critical difference of the Nemenyi test for this design: {num(cd,2,lang)} ranks. ", f"Différence critique du test de Nemenyi pour ce plan : {num(cd,2,lang)} rangs. ", lang) + src(['output_mechanism/metrics/mechanism_ranks_long.csv'], lang)))
    rows = "\n".join(f"{int(r.gap_length) if not pd.isna(r.gap_length) else T('1 to 8','1 à 8',lang)} & {T('Ranking','Classement',lang) if r.analysis=='ranking_agreement' else T('Direction of rank change','Sens du changement de rang',lang)} & {MECH[r.mechanism_a][0 if lang=='en' else 1]} & {MECH[r.mechanism_b][0 if lang=='en' else 1]} & {num(r.rho,2,lang,sign=True)} & {pval(r.p_value,lang)} \\\\" for _, r in at.iterrows())
    out.append(table_env(t_at, T('Spearman agreement between mechanisms.', 'Accord de Spearman entre mécanismes.', lang), 'rlllrr',
                         T(r"Gap (weeks) & Comparison & Mechanism A & Mechanism B & $\rho$ & $p$ \\", r"Lacune (sem.) & Comparaison & Mécanisme A & Mécanisme B & $\rho$ & $p$ \\", lang), rows,
                         src(['output_mechanism/metrics/mechanism_agreement_tests.csv'], lang)))

    # 5. peak detection by gap length
    yg = rd(MET, 'youden_by_gap.csv')
    py = rd(MET, 'paired_youden.csv')
    t_yg = nb.table('S_youden_gap', 6)
    rows = []
    for m in order:
        cells = []
        for g in [1, 4, 8]:
            r = yg[(yg.gap_length == g) & (yg.method == m)].iloc[0]
            cells.append(f"{num(r.youden,3,lang)} ({int(r.rank_youden)}) & {int(r.rank_MAE)}")
        rows.append(f"{mname(m,lang)} & " + ' & '.join(cells) + r" \\")
    pr = []
    for _, r in py.iterrows():
        pr.append(T(f"{int(r.gap_length)}-week gaps: {mname(r.method_a,lang)} {num(r.youden_a,3,lang)} against {mname(r.method_b,lang)} {num(r.youden_b,3,lang)}, higher in {int(r.blocks_a_higher)} of {int(r.n_blocks)} blocks ({int(r.blocks_tied)} tied), paired Wilcoxon $p$ = {pval(r.wilcoxon_p,lang)}",
                    f"lacunes de {int(r.gap_length)} semaine{'s' if r.gap_length > 1 else ''} : {mname(r.method_a,lang)} {num(r.youden_a,3,lang)} contre {mname(r.method_b,lang)} {num(r.youden_b,3,lang)}, supérieure dans {int(r.blocks_a_higher)} blocs sur {int(r.n_blocks)} ({int(r.blocks_tied)} ex aequo), Wilcoxon apparié $p$ = {pval(r.wilcoxon_p,lang)}", lang))
    pw = rd(MET, 'peak_weeks_per_mask.csv')
    pw_txt = T('; ', ' ; ', lang).join(
        T(f"{num(r.missing_rate,0,lang)}\\% and {int(r.gap_length)} week{'s' if r.gap_length > 1 else ''}: {num(r.median_n_peaks,1,lang)} ({int(r.min_n_peaks)} to {int(r.max_n_peaks)})",
          f"{num(r.missing_rate,0,lang)}~\\% et {int(r.gap_length)} semaine{'s' if r.gap_length > 1 else ''} : {num(r.median_n_peaks,1,lang)} ({int(r.min_n_peaks)} à {int(r.max_n_peaks)})", lang)
        for _, r in pw.iterrows())
    out.append(T(r"\subsection*{5. Detection of high-incidence weeks by gap length}", r"\subsection*{5. Détection des semaines de forte incidence par longueur de lacune}", lang))
    out.append(table_env(t_yg, T('Youden index (rank among the ten methods) and rank on mean absolute error, by gap length.', 'Indice de Youden (rang parmi les dix méthodes) et rang sur l\'erreur absolue moyenne, par longueur de lacune.', lang),
                         'lrrrrrr', ' & ' + ' & '.join(r"\multicolumn{2}{c}{%s}" % x for x in T(['1 week', '4 weeks', '8 weeks'], ['1 semaine', '4 semaines', '8 semaines'], lang)) + r" \\" + "\n" + T('Method', 'Méthode', lang) + ' & ' + ' & '.join([T('Youden & MAE rank', 'Youden & Rang MAE', lang)] * 3) + r" \\",
                         "\n".join(rows), T("Paired comparisons: ", "Comparaisons appariées : ", lang) + T('; ', ' ; ', lang).join(pr) + '. '
                         + T("Masked weeks above the threshold per mask, eleven districts pooled, median (range): ", "Semaines masquées au-dessus du seuil par masque, onze districts réunis, médiane (étendue) : ", lang) + pw_txt + '. '
                         + src(['output/metrics/youden_by_gap.csv', 'output/metrics/paired_youden.csv', 'output/metrics/peak_weeks_per_mask.csv'], lang)))

    # 6. forecasting diagnostic
    fs = rd(MET, 'forecast_leakage_summary.csv').set_index('criterion')
    fd = rd(MET, 'forecast_leakage_diagnostic.csv')
    t_fd = nb.table('S_forecast', 6)
    rows = "\n".join(f"{mname(r.method,lang)} & {r.variant} & {num(r.MAE,1,lang)} & {num(r.degradation_h4_all,2,lang)} & {num(r.degradation_h4_clean,2,lang)} & {num(r.degradation_h4_exposed,2,lang)} \\\\" for _, r in fd.sort_values('MAE').iterrows())
    rows += "\n\\midrule\n" + T("Spearman $\\rho$ with MAE ($p$)", "$\\rho$ de Spearman avec la MAE ($p$)", lang) + " & & & " + ' & '.join(f"{num(fs.loc[c,'spearman_with_MAE'],2,lang,sign=True)} ({pval(fs.loc[c,'p_value'],lang)})" for c in ['degradation_h4_all', 'degradation_h4_clean', 'degradation_h4_exposed']) + r" \\"
    out.append(T(r"\subsection*{6. Forecasting analysis: leakage diagnostic}", r"\subsection*{6. Analyse de prévision : diagnostic de fuite}", lang))
    out.append(table_env(t_fd, T(f'Degradation of the four-week forecast error (RMSE, imputed minus reference), one-week gaps, first five repetitions, over all origins and separately over non-exposed and exposed origins ({pct(100*fd.share_origins_exposed.iloc[0],1,lang)} of origins exposed).',
                                 f'Dégradation de l\'erreur de prévision à quatre semaines (RMSE, série imputée moins référence), lacunes d\'une semaine, cinq premières répétitions, sur toutes les origines puis séparément sur les origines non exposées et exposées ({pct(100*fd.share_origins_exposed.iloc[0],1,lang)} des origines exposées).', lang),
                         'llrrrr', T(r"Method & Predictors & MAE & All origins & Non-exposed & Exposed \\", r"Méthode & Prédicteurs & MAE & Toutes origines & Non exposées & Exposées \\", lang), rows,
                         T(f"An origin is exposed when at least one of the {int(fs.lookback_weeks.iloc[0])} weeks before it was masked. ", f"Une origine est exposée quand l'une au moins des {int(fs.lookback_weeks.iloc[0])} semaines qui la précèdent était masquée. ", lang) + src(['output/metrics/forecast_leakage_diagnostic.csv', 'output/metrics/forecast_leakage_summary.csv'], lang), size='scriptsize'))

    # 7. step 8b: NoTime block only, Kalman vs linear interpolation, forests by block (R/11 section 13)
    nf = rd(MET, 'friedman_notime_by_gap.csv').set_index('gap_length')
    nr = rd(MET, 'friedman_ranks_notime_by_gap.csv')
    nn = rd(MET, 'nemenyi_pairs_notime_by_gap.csv')
    kl = rd(MET, 'paired_kalman_linearinterp.csv')
    fb8 = rd(MET, 'paired_forest_blocks_gap8.csv')
    t_nf, t_nn = nb.table('S_notime_friedman', 6), nb.table('S_notime_nemenyi', 6)
    t_kl, t_fb = nb.table('S_kal_li', 6), nb.table('S_forest_blocks', 6)
    out.append(T(r"\subsection*{7. NoTime block only, and paired comparisons}", r"\subsection*{7. Bloc NoTime seul, et comparaisons appariées}", lang))
    piv = nr.pivot(index='method', columns='gap_length', values='mean_rank')
    piv = piv.loc[piv[8].sort_values().index]
    rows = "\n".join(f"{mname(m,lang)} & " + ' & '.join(num(piv.loc[m, g], 2, lang) for g in [1, 4, 8]) + r" \\" for m in piv.index)
    rows += "\n\\midrule\n" + "$\\chi^2$ (" + T('9 df', '9 ddl', lang) + ") & " + ' & '.join(num(nf.loc[g, 'chi_squared'], 1, lang) for g in [1, 4, 8]) + r" \\"
    rows += "\n$p$ & " + ' & '.join(pval(nf.loc[g, 'p_value'], lang) for g in [1, 4, 8]) + r" \\"
    rows += "\n" + T('Critical difference', 'Différence critique', lang) + " & " + ' & '.join(num(nf.loc[g, 'cd'], 2, lang) for g in [1, 4, 8]) + r" \\"
    out.append(table_env(t_nf, T('Mean Friedman rank of the ten methods over the 60 blocks with the NoTime block only (no seasonal or trend covariate for any method), by gap length; methods ordered by their rank at eight weeks.',
                                 'Rang moyen de Friedman des dix méthodes sur les 60 blocs avec le seul bloc NoTime (aucune covariable saisonnière ni de tendance pour aucune méthode), par longueur de lacune ; méthodes classées selon leur rang à huit semaines.', lang),
                         'lrrr', T(r"Method & 1 week & 4 weeks & 8 weeks \\", r"Méthode & 1 semaine & 4 semaines & 8 semaines \\", lang), rows,
                         src(['output/metrics/friedman_notime_by_gap.csv', 'output/metrics/friedman_ranks_notime_by_gap.csv'], lang)))
    rows = []
    for g in [4, 8]:
        top = nr[nr.gap_length == g].nsmallest(5, 'mean_rank').method.tolist()
        sub = nn[(nn.gap_length == g) & nn.method_a.isin(top) & nn.method_b.isin(top)].copy()
        sub['key'] = sub.apply(lambda r: min(top.index(r.method_a), top.index(r.method_b)) * 10 + max(top.index(r.method_a), top.index(r.method_b)), axis=1)
        assert len(sub) == 10
        for _, r in sub.sort_values('key').iterrows():
            a, b = sorted([r.method_a, r.method_b], key=top.index)
            rows.append(f"{g} & {mname(a,lang)} & {mname(b,lang)} & {num(r.rank_diff,2,lang)} & {pval(r.p_nemenyi,lang)} & {T('yes','oui',lang) if r.exceeds_cd else T('no','non',lang)} \\\\")
        rows.append(r"\addlinespace[2pt]")
    out.append(table_env(t_nn, T('Nemenyi comparisons between the five leading methods at four and eight weeks, NoTime block only.', 'Comparaisons de Nemenyi entre les cinq premières méthodes à quatre et huit semaines, bloc NoTime seul.', lang),
                         'rllrrr', T(r"Gap & Method A & Method B & Rank difference & $p$ & Exceeds CD \\", r"Lacune & Méthode A & Méthode B & Écart de rang & $p$ & Dépasse la DC \\", lang),
                         "\n".join(rows[:-1]), src(['output/metrics/nemenyi_pairs_notime_by_gap.csv'], lang)))
    rows = "\n".join(f"{int(r.gap_length)} & {num(r.mae_kalman,1,lang)} & {num(r.mae_linearinterp,1,lang)} & {num(r.mean_diff,2,lang)} & {num(r.pct_diff_vs_linearinterp,1,lang)} & {int(r.blocks_won_by_kalman)}/{int(r.n_blocks)} & {pval(r.wilcoxon_p,lang)} & {pval(r.sign_test_p,lang)} \\\\" for _, r in kl.iterrows())
    out.append(table_env(t_kl, T('Kalman smoothing against linear interpolation, paired over the 60 blocks, by gap length (NoTime is the only block of both methods).', 'Lissage de Kalman contre interpolation linéaire, appariés sur les 60 blocs, par longueur de lacune (NoTime est le seul bloc des deux méthodes).', lang),
                         'rrrrrrrr', T(r"Gap & MAE & MAE & Difference & Difference & Blocks won & Wilcoxon & Sign test \\ (weeks) & Kalman & interpolation & (cases) & (\%) & by Kalman & $p$ & $p$ \\", r"Lacune & MAE & MAE & Écart & Écart & Blocs gagnés & Wilcoxon & Test du signe \\ (sem.) & Kalman & interpolation & (cas) & (\%) & par Kalman & $p$ & $p$ \\", lang),
                         rows, src(['output/metrics/paired_kalman_linearinterp.csv'], lang)))
    rows = []
    for (m, v), d in fb8.groupby(['method', 'variant'], sort=False):
        for _, r in d.iterrows():
            rows.append(f"{mname(m,lang) if r.comparator == d.comparator.iloc[0] else ''} & {r.variant if r.comparator == d.comparator.iloc[0] else ''} & {num(r.mae_forest,1,lang) if r.comparator == d.comparator.iloc[0] else ''} & {mname(r.comparator,lang)} & {num(r.mae_comparator,1,lang)} & {num(r.mean_diff,2,lang)} & {int(r.blocks_won_by_forest)}/{int(r.n_blocks)} & {pval(r.wilcoxon_p,lang)} \\\\")
        rows.append(r"\addlinespace[2pt]")
    out.append(table_env(t_fb, T('MissForest and MissForest-ST under each predictor block, eight-week gaps, paired over the 60 blocks with Kalman smoothing, linear interpolation and seasonal decomposition (NoTime).',
                                 'MissForest et MissForest-ST sous chaque bloc de prédicteurs, lacunes de huit semaines, appariés sur les 60 blocs avec le lissage de Kalman, l\'interpolation linéaire et la décomposition saisonnière (NoTime).', lang),
                         'llrlrrrr', T(r"Forest & Block & MAE & Comparator & MAE & Difference & Blocks won & Wilcoxon $p$ \\", r"Forêt & Bloc & MAE & Comparateur & MAE & Écart & Blocs gagnés & Wilcoxon $p$ \\", lang),
                         "\n".join(rows[:-1]), T("Difference: forest minus comparator, in cases per week; blocks won by the forest. ", "Écart : forêt moins comparateur, en cas par semaine ; blocs gagnés par la forêt. ", lang) + src(['output/metrics/paired_forest_blocks_gap8.csv'], lang), size='scriptsize'))
    return "\n\n".join(out) + "\n"


# ================================================================== assembly
PREAMBLE = r"""\documentclass[11pt,a4paper]{article}
\usepackage[T1]{fontenc}
\usepackage[utf8]{inputenc}
\usepackage{lmodern}
\usepackage[margin=22mm]{geometry}
\usepackage{booktabs,array,graphicx,caption,placeins}
\usepackage[hidelinks]{hyperref}
\captionsetup{font=small,labelfont=bf,labelsep=period,justification=raggedright,singlelinecheck=false}
\setlength{\parindent}{0pt}
\setlength{\parskip}{6pt}
\emergencystretch=3em
\renewcommand{\thetable}{S\arabic{table}}
\renewcommand{\thefigure}{S\arabic{figure}}
\newcommand{\code}[1]{\texttt{\small #1}}
%%LANG%%
\begin{document}
{\small\textbf{%%AFNAME%%}\\
%%AUTHORS%%. %%TITLE%%.\par}
\vspace{4pt}\hrule\vspace{10pt}
"""
LANG_FR = r"""\renewcommand{\tablename}{Tableau}
\renewcommand{\figurename}{Figure}
\frenchspacing"""
BUILDERS = [af1, af2, af3, af4, af5, af6]


def breakable(tex):
    tex = tex.replace('\\subsection*', '\\FloatBarrier\n\\subsection*')
    def fix(m):
        return '\\code{' + m.group(1).replace('/', '/\\allowbreak ').replace('\\_', '\\_\\allowbreak ') + '}'
    return re.sub(r'\\code\{([^{}]*)\}', fix, tex)


def fname(n, lang):
    return f"Additional_file_{n}" if lang == 'en' else f"Fichier_additionnel_{n}"


def write_all():
    numbering = None
    for lang in ('en', 'fr'):
        nb = Numbering()
        for n, build in enumerate(BUILDERS, start=1):
            body = build(lang, nb).replace('= $<$', '$<$')
            pre = (PREAMBLE.replace('%%LANG%%', LANG_FR if lang == 'fr' else '')
                   .replace('%%AFNAME%%', f"Additional file {n}" if lang == 'en' else f"Fichier additionnel {n}")
                   .replace('%%AUTHORS%%', AUTHORS).replace('%%TITLE%%', TITLE[lang]))
            with open(os.path.join(OUT, fname(n, lang) + '.tex'), 'w', encoding='utf-8') as f:
                f.write(pre + breakable(body) + "\\end{document}\n")
        if numbering is None:
            numbering = nb.rows
        assert nb.rows == numbering, 'EN and FR numbering differ'
    with open(os.path.join(OUT, 'supplement_numbering.csv'), 'w', newline='', encoding='utf-8') as f:
        w = csv.writer(f)
        w.writerow(['key', 'additional_file', 'kind', 'number'])
        w.writerows(numbering)
    for k, af, kind, n in numbering:
        print(f"  {kind:6s} S{n:<3d} AF{af}  {k}")


def compile_all():
    ok = True
    for lang in ('en', 'fr'):
        for n in range(1, len(BUILDERS) + 1):
            base = fname(n, lang)
            for _ in range(2):
                r = subprocess.run(['pdflatex', '-interaction=nonstopmode', '-halt-on-error', base + '.tex'],
                                   cwd=OUT, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
            log = open(os.path.join(OUT, base + '.log'), encoding='latin-1').read()
            over = len(re.findall(r'Overfull \\hbox \((\d+\.\d+)pt', log))
            ok &= r.returncode == 0
            print(f"{base}.pdf : {'OK' if r.returncode == 0 else 'ERROR'}, overfull boxes: {over}")
    return ok


if __name__ == '__main__':
    write_all()
    if '--no-pdf' not in sys.argv:
        sys.exit(0 if compile_all() else 1)
